using System;using UnityEditor;using UnityEditor.SceneManagement;using UnityEditor.Build.Reporting;using UnityEngine;
public static class GuiTextureAdapterProbeBuild {public static void Run(){var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var camera=new GameObject("Same Linear HDR camera").AddComponent<Camera>();camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;camera.gameObject.AddComponent<LighFight.Runtime.FittedFilmicCamera>().filmicShader=AssetDatabase.LoadAssetAtPath<Shader>("Assets/LighFight/Resources/Shaders/FittedFilmic.shader");var probe=new GameObject("Owned GPU cache transport experiment").AddComponent<GuiTextureAdapterProbe>();probe.viewCamera=camera;probe.portrait=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/GuiColorProbe/actual-fighter-0.png");probe.flat=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/GuiColorProbe/flat-srgb.png");probe.extraDecode=AssetDatabase.LoadAssetAtPath<Shader>("Assets/GuiColorProbe/GuiExtraDecode.shader");probe.linearDraw=AssetDatabase.LoadAssetAtPath<Shader>("Assets/GuiColorProbe/GuiLinearDraw.shader");if(ShaderUtil.ShaderHasError(probe.extraDecode)||ShaderUtil.ShaderHasError(probe.linearDraw))throw new Exception("GUI transfer shader failed");EditorSceneManager.SaveScene(scene,"Assets/GuiColorProbe/Adapter.unity");AssetDatabase.SaveAssets();var report=BuildPipeline.BuildPlayer(new[]{"Assets/GuiColorProbe/Adapter.unity"},"GuiColorProbeBuild/GuiColorProbe.app",BuildTarget.StandaloneOSX,BuildOptions.Development);if(report.summary.result!=BuildResult.Succeeded)throw new Exception("GUI adapter build failed");}}
